.stage {
  --bg: #0b0f14; --ink: #f4f6f8; --muted: #8a94a3; --accent: #5eead4; --accent-soft: #134e4a; --surface: #151b24;
  position: absolute; inset: 0; overflow: hidden; background: var(--bg); color: var(--ink);
  font-family: inter, sans-serif; font-weight: 400;
}
.scene { position: absolute; inset: 0; }
.glow {
  position: absolute; left: 1010px; top: 90px; width: 900px; height: 900px; border-radius: 50%;
  background: radial-gradient(circle, var(--accent-soft) 0%, transparent 68%); opacity: 0.45;
}
.kicker { position: absolute; left: 160px; top: 150px; margin: 0; font-family: space-grotesk, sans-serif; font-size: 44px; letter-spacing: 6px; color: var(--muted); white-space: nowrap; }

/* scene 1: two cards in a fading scene */
.card {
  position: absolute; top: 260px; width: 700px; height: 420px; box-sizing: border-box;
  background: var(--surface); border: 2px solid #2a3442; border-radius: 28px; box-shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
}
.c1 { left: 160px; }
.c2 { left: 960px; }
.ct { position: absolute; left: 48px; top: 48px; margin: 0; font-family: space-grotesk, sans-serif; font-weight: 700; font-size: 56px; line-height: 1.1; white-space: nowrap; }
.cb { position: absolute; left: 48px; top: 150px; width: 600px; margin: 0; font-size: 34px; line-height: 1.4; color: var(--muted); }

/* scene 2: a clip that cuts (the line rises from below it) and a clip that cuts nothing */
.k2 { top: 220px; }
.reveal { position: absolute; left: 160px; top: 340px; width: 1500px; height: 150px; overflow: hidden; }
.line { position: absolute; left: 0; top: 0; font-family: space-grotesk, sans-serif; font-weight: 700; font-size: 100px; line-height: 150px; white-space: nowrap; }
.pill { position: absolute; left: 160px; top: 620px; width: 840px; height: 110px; overflow: hidden; border-radius: 55px; background: var(--accent-soft); }
.pt, .pt2 { position: absolute; top: 28px; margin: 0; font-size: 46px; line-height: 54px; white-space: nowrap; }
.pt { left: 48px; color: var(--ink); font-weight: 700; }
.pt2 { left: 360px; color: var(--accent); }

.s1 { animation: life 5s cubic-bezier(0.65, 0, 0.35, 1) 0s both; }
.s2 { animation: life 5s cubic-bezier(0.65, 0, 0.35, 1) 5s both; }
.c1 { animation: rise 0.8s cubic-bezier(0.19, 1, 0.22, 1) 0.3s both; }
.c2 { animation: rise 0.8s cubic-bezier(0.19, 1, 0.22, 1) 0.6s both; }
.line { animation: up 0.9s cubic-bezier(0.19, 1, 0.22, 1) 5.5s both; }
.pill { animation: fade 0.6s cubic-bezier(0.215, 0.61, 0.355, 1) 6.2s both; }

@keyframes life { 0% { opacity: 0; } 8% { opacity: 1; } 92% { opacity: 1; } 100% { opacity: 0; } }
@keyframes rise { from { opacity: 0; transform: translateY(48px); } to { opacity: 1; transform: none; } }
@keyframes up { from { transform: translateY(160px); } to { transform: none; } }
@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
